# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
import torch
import triton
import triton.language as tl


@triton.jit(do_not_specialize=["mini", "maxi"])
def _clip_kernel(
    A_ptr,
    mini,
    maxi,
    N,
    HAS_MIN: tl.constexpr,
    HAS_MAX: tl.constexpr,
    BLOCK: tl.constexpr,
    UNROLL: tl.constexpr,
    EVEN: tl.constexpr,
):
    # Homogeneous native-dtype clamp: materialize the scalar bounds as full
    # vectors in the tensor's own element type so tl.minimum/tl.maximum lower
    # to vector-pipe vmin/vmax instead of a scalar-pipe scalar x vector compare.
    # Clamp to scalar bounds is exact in the source dtype (bounds -0.5/0.5 are
    # exactly representable in fp16/bf16/fp32), matching torch.clip_ bit-exact.
    #
    # The bound vectors are materialized once per program, OUTSIDE the
    # grid-stride loop. A persistent grid (grid == num_vectorcore) makes this
    # prologue cost negligible: only ~40 programs broadcast the bounds instead
    # of one broadcast per tile as in a flat one-tile-per-program grid.
    #
    # The grid-stride loop is UNROLL-way unrolled with BATCHED memory ops:
    # all UNROLL MTE2 loads are issued back to back before the VEC clamps and
    # MTE3 stores, exposing UNROLL outstanding in-flight tiles of memory-level
    # parallelism. Round-8 profiling showed the 2x-unroll still left the 1Gi
    # streaming workloads unsaturated (fp32 mte2 41%, fp16 mte2 33%), so more
    # outstanding loads overlap the HBM latency. Tiles 1..UNROLL-1 are always
    # bounds-masked, which is exact for every N and preserves bit-exact
    # equality with torch.clip_. UNROLL is chosen per-dtype at dispatch time:
    # UNROLL=4 for 2-byte dtypes (fp16/bf16) and UNROLL=3 for fp32, the
    # largest unroll still fitting the AIV unified buffer at BLOCK=4096
    # (UNROLL=4 x fp32 x BLOCK=4096 overflows: 1577216 vs 1572864 bits).
    dtype = A_ptr.dtype.element_ty
    if HAS_MIN:
        mini_v = tl.full((BLOCK,), mini, dtype)
    if HAS_MAX:
        maxi_v = tl.full((BLOCK,), maxi, dtype)

    pid = tl.program_id(0)
    nprog = tl.num_programs(0)
    start = pid * BLOCK
    step = nprog * BLOCK
    if EVEN:
        # N % BLOCK == 0 and every loop offset is a multiple of BLOCK, so the
        # first tile is always fully in-bounds; only tiles 1..UNROLL-1 can
        # spill past N and need a bounds mask.
        if UNROLL == 4:
            for off in range(start, N, 4 * step):
                offs0 = off + tl.arange(0, BLOCK)
                offs1 = offs0 + step
                offs2 = offs1 + step
                offs3 = offs2 + step
                m1 = offs1 < N
                m2 = offs2 < N
                m3 = offs3 < N
                v0 = tl.load(A_ptr + offs0)
                v1 = tl.load(A_ptr + offs1, mask=m1)
                v2 = tl.load(A_ptr + offs2, mask=m2)
                v3 = tl.load(A_ptr + offs3, mask=m3)
                if HAS_MIN:
                    v0 = tl.maximum(mini_v, v0)
                    v1 = tl.maximum(mini_v, v1)
                    v2 = tl.maximum(mini_v, v2)
                    v3 = tl.maximum(mini_v, v3)
                if HAS_MAX:
                    v0 = tl.minimum(maxi_v, v0)
                    v1 = tl.minimum(maxi_v, v1)
                    v2 = tl.minimum(maxi_v, v2)
                    v3 = tl.minimum(maxi_v, v3)
                tl.store(A_ptr + offs0, v0)
                tl.store(A_ptr + offs1, v1, mask=m1)
                tl.store(A_ptr + offs2, v2, mask=m2)
                tl.store(A_ptr + offs3, v3, mask=m3)
        elif UNROLL == 3:
            for off in range(start, N, 3 * step):
                offs0 = off + tl.arange(0, BLOCK)
                offs1 = offs0 + step
                offs2 = offs1 + step
                m1 = offs1 < N
                m2 = offs2 < N
                v0 = tl.load(A_ptr + offs0)
                v1 = tl.load(A_ptr + offs1, mask=m1)
                v2 = tl.load(A_ptr + offs2, mask=m2)
                if HAS_MIN:
                    v0 = tl.maximum(mini_v, v0)
                    v1 = tl.maximum(mini_v, v1)
                    v2 = tl.maximum(mini_v, v2)
                if HAS_MAX:
                    v0 = tl.minimum(maxi_v, v0)
                    v1 = tl.minimum(maxi_v, v1)
                    v2 = tl.minimum(maxi_v, v2)
                tl.store(A_ptr + offs0, v0)
                tl.store(A_ptr + offs1, v1, mask=m1)
                tl.store(A_ptr + offs2, v2, mask=m2)
        else:
            # UNROLL == 2 (round-8 behavior for the small launch-bound shapes)
            for off in range(start, N, 2 * step):
                offs0 = off + tl.arange(0, BLOCK)
                offs1 = offs0 + step
                m1 = offs1 < N
                v0 = tl.load(A_ptr + offs0)
                v1 = tl.load(A_ptr + offs1, mask=m1)
                if HAS_MIN:
                    v0 = tl.maximum(mini_v, v0)
                    v1 = tl.maximum(mini_v, v1)
                if HAS_MAX:
                    v0 = tl.minimum(maxi_v, v0)
                    v1 = tl.minimum(maxi_v, v1)
                tl.store(A_ptr + offs0, v0)
                tl.store(A_ptr + offs1, v1, mask=m1)
    else:
        # Non-even N (not hit by the benchmark shapes, which are exact
        # multiples of BLOCK): plain masked grid-stride loop, always correct.
        for off in range(start, N, step):
            offs = off + tl.arange(0, BLOCK)
            mask = offs < N
            v = tl.load(A_ptr + offs, mask=mask)
            if HAS_MIN:
                v = tl.maximum(mini_v, v)
            if HAS_MAX:
                v = tl.minimum(maxi_v, v)
            tl.store(A_ptr + offs, v, mask=mask)


# Ascend rtKernelLaunch limits a single grid dimension (coreDim) to 65535.
# This is an API/launch parameter bound, not a physical AI Core count, and is
# valid on all Ascend910B variants (B2/B3/B4). It is only used as a safety
# cap when the persistent-grid device query is unavailable.
_MAX_GRID_DIM = 65535


def _num_vectorcore():
    # Pure Vector kernel (elementwise min/max), so num_vectorcore is the right
    # residency query per the Ascend portability contract. Query the actual
    # target at runtime so the candidate is correct on Ascend910B2 as well as
    # the B4 development device; never bake in a physical core count.
    try:
        import triton.runtime.driver as driver

        props = driver.active.utils.get_device_properties(torch.npu.current_device())
        return int(props["num_vectorcore"])
    except Exception:
        return None


def _launch(A_flat, mini, maxi, has_min, has_max, N, elem_size, is_fp16):
    # Large tensors (N >= 1Mi):
    #   - fp16: BLOCK=8192 x UNROLL=3. Round-10 debug sweep showed a wider tile
    #     with fewer loop iterations beats BLOCK=4096 x UNROLL=4 for fp16
    #     (mid 2.42x vs 1.89x, 1Gi 1.78x vs 1.50x) because the fp16 clamp lowers
    #     to a narrow vmin/vmax that still fits the AIV unified buffer at
    #     BLOCK=8192, while the fewer iterations cut loop/index overhead.
    #   - bf16: BLOCK=4096 x UNROLL=4. BLOCK=8192 overflows the UB for bf16
    #     (its min/max passes through fp32 conversion buffers), so the wide
    #     tile is not usable there.
    #   - fp32: BLOCK=4096 x UNROLL=3. BLOCK=8192 overflows the UB for fp32.
    # Small tensors: BLOCK=1024 with UNROLL=2, which keeps the round-8 small
    # workload behavior unchanged (the [64,64] shapes are launch/latency-bound
    # and gain nothing from deeper unrolling or wider tiles).
    if N >= (1 << 20):
        if is_fp16:
            if N % 8192 == 0:
                BLOCK = 8192
                UNROLL = 3
            else:
                BLOCK = 4096
                UNROLL = 4
        else:
            BLOCK = 4096
            UNROLL = 4 if elem_size == 2 else 3
    else:
        BLOCK = 1024
        UNROLL = 2

    num_ctas = (N + BLOCK - 1) // BLOCK
    nvec = _num_vectorcore()
    if nvec is not None:
        # Persistent grid: one resident program per vector core, grid-stride
        # loop strides by the ACTUAL launched program count (tl.num_programs(0)),
        # never by a hard-coded B4 core count.
        grid = (min(num_ctas, nvec),)
    else:
        # Query unavailable: fall back to the task-derived grid with the API
        # cap. This remains correct (grid-stride loop covers the remainder).
        num_ctas = min(num_ctas, _MAX_GRID_DIM)
        grid = (num_ctas,)

    even = (N % BLOCK) == 0
    _clip_kernel[grid](
        A_flat,
        mini,
        maxi,
        N,
        has_min,
        has_max,
        BLOCK=BLOCK,
        UNROLL=UNROLL,
        EVEN=even,
    )


def clip_(A, mini=None, maxi=None):
    if mini is None and maxi is None:
        raise ValueError("At least one of 'mini' or 'maxi' must not be None")

    N = A.numel()
    if N == 0:
        return A

    has_min = mini is not None
    has_max = maxi is not None
    mini_v = float(mini) if has_min else 0.0
    maxi_v = float(maxi) if has_max else 0.0

    if A.is_contiguous():
        A_flat = A.view(-1)
        _launch(
            A_flat,
            mini_v,
            maxi_v,
            has_min,
            has_max,
            N,
            A.element_size(),
            A.dtype == torch.float16,
        )
    else:
        A_contig = A.contiguous()
        _launch(
            A_contig.view(-1),
            mini_v,
            maxi_v,
            has_min,
            has_max,
            N,
            A.element_size(),
            A.dtype == torch.float16,
        )
        A.copy_(A_contig)

    return A
